(()=>{const story=document.querySelector('.case-story');if(!story)return;const track=document.querySelector('.reading-track span'),label=document.querySelector('.reading-label b');let pending=false;function progress(){const start=story.getBoundingClientRect().top+scrollY,end=start+story.offsetHeight-innerHeight*.65,value=Math.max(0,Math.min(100,(scrollY+innerHeight*.2-start)/(end-start)*100));if(track)track.style.width=value+'%';if(label)label.textContent=Math.round(value)+'%';pending=false}addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(progress)}},{passive:true});progress();let buttons=[...document.querySelectorAll('.image-enlarge')];if(!buttons.length)return;const dialog=document.createElement('dialog');dialog.className='process-lightbox';dialog.setAttribute('aria-label','项目图文浏览');dialog.innerHTML='<div class="lightbox-tools"><span class="lightbox-position"></span><div><button type="button" data-action="previous" aria-label="上一张">←</button><button type="button" data-action="next" aria-label="下一张">→</button><button type="button" data-action="close" aria-label="关闭图片">关闭 ×</button></div></div><div class="ed-lightbox-stage"></div><p class="lightbox-caption"></p>';document.body.append(dialog);let index=0;function show(i){index=Math.max(0,Math.min(buttons.length-1,i));const button=buttons[index],source=button.querySelector('.ed-visual');const stage=dialog.querySelector('.ed-lightbox-stage');if(source){const clone=source.cloneNode(true);[clone,...clone.querySelectorAll('[data-edit-key]')].forEach(el=>{el.removeAttribute('data-edit-key');el.removeAttribute('data-edit-kind')});clone.querySelectorAll('img').forEach(im=>{im.loading='eager';im.removeAttribute('data-placement-key');im.removeAttribute('data-original-node')});stage.replaceChildren(clone)}else{const img=button.querySelector('img').cloneNode();img.loading='eager';stage.replaceChildren(img)}dialog.querySelector('.lightbox-caption').textContent=button.dataset.caption||button.querySelector('img')?.alt||'';dialog.querySelector('.lightbox-position').textContent=String(index+1).padStart(2,'0')+' / '+String(buttons.length).padStart(2,'0');dialog.querySelector('[data-action="previous"]').disabled=index===0;dialog.querySelector('[data-action="next"]').disabled=index===buttons.length-1}buttons.forEach(button=>button.addEventListener('click',()=>{buttons=[...document.querySelectorAll('.image-enlarge')];show(buttons.indexOf(button));dialog.showModal()}));dialog.querySelector('[data-action="close"]').addEventListener('click',()=>dialog.close());dialog.querySelector('[data-action="previous"]').addEventListener('click',()=>show(index-1));dialog.querySelector('[data-action="next"]').addEventListener('click',()=>show(index+1));dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();show(index-1)}if(e.key==='ArrowRight'){e.preventDefault();show(index+1)}});dialog.addEventListener('click',e=>{if(e.target===dialog){const box=dialog.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)dialog.close()}})})();
